import {
	AbsoluteFill,
	Img,
	interpolate,
	OffthreadVideo,
	Sequence,
	staticFile,
	useCurrentFrame,
} from 'remotion';
import {z} from 'zod';
import {BRAND} from '../config';
import {EASE_ENTER, EASE_EXIT} from '../motion';
import {BrandWatermark, brandWatermarkSchema} from './BrandWatermark';
import {EndCard} from './EndCard';

// A punchy before/after reveal: a still "before" image held with a faint
// living zoom, a fast whip-blur+flash cut, then a "after" clip (generated by
// animating the matching after-still with Kling image-to-video) — followed
// by the brand end card. The before deliberately never moves much: the
// contrast between "static" and "suddenly alive" IS the reveal.
export const beforeAfterRevealSchema = z.object({
	beforeImageSrc: z.string(),
	afterVideoSrc: z.string(),
	beforeHoldFrames: z.number(),
	afterDurationFrames: z.number(),
	labelBefore: z.string(),
	labelAfter: z.string(),
	...brandWatermarkSchema.shape,
	endCardHeadlineLine1: z.string(),
	endCardHeadlineLine2: z.string(),
	endCardTagline: z.string(),
	endCardUrl: z.string(),
	endCardBackgroundColor: z.string(),
	endCardAccentColor2: z.string(),
});

export const beforeAfterRevealDefaultProps: z.infer<
	typeof beforeAfterRevealSchema
> = {
	beforeImageSrc: 'before-after/glowup-before.png',
	afterVideoSrc: 'before-after/glowup-after-video.mp4',
	beforeHoldFrames: 45,
	afterDurationFrames: 121,
	labelBefore: 'BEFORE',
	labelAfter: 'AFTER',
	iconSrc: 'brand/facestylefun-icon.png',
	wordmarkPrimary: 'facestyle',
	wordmarkAccent: '.fun',
	textColor: BRAND.white,
	accentColor: BRAND.cyan,
	plateColor: BRAND.navy,
	corner: 'topRight',
	iconSize: 64,
	endCardHeadlineLine1: 'One Photo.',
	endCardHeadlineLine2: 'Infinite Styles.',
	endCardTagline: 'AI Face. Your Style.',
	endCardUrl: 'facestyle.fun',
	endCardBackgroundColor: BRAND.navy,
	endCardAccentColor2: BRAND.purple,
};

// Half-width of the whip transition, in frames, centered on the cut.
const WHIP_HALF_WIDTH = 4;
const LABEL_PLATE = `${BRAND.navy}8C`;

const Label: React.FC<{
	text: string;
	opacity: number;
	scale: number;
	side: 'left' | 'right';
}> = ({text, opacity, scale, side}) => (
	<div
		style={{
			position: 'absolute',
			bottom: 48,
			[side]: 40,
			opacity,
			transform: `scale(${scale})`,
			padding: '10px 22px',
			borderRadius: 999,
			backgroundColor: LABEL_PLATE,
			backdropFilter: 'blur(6px)',
			fontFamily: 'Arial, Helvetica, sans-serif',
			fontWeight: 800,
			fontSize: 26,
			letterSpacing: 3,
			color: BRAND.white,
		}}
	>
		{text}
	</div>
);

const Reveal: React.FC<{
	beforeImageSrc: string;
	afterVideoSrc: string;
	beforeHoldFrames: number;
	labelBefore: string;
	labelAfter: string;
}> = ({beforeImageSrc, afterVideoSrc, beforeHoldFrames, labelBefore, labelAfter}) => {
	const frame = useCurrentFrame();
	const cutFrame = beforeHoldFrames;
	const isAfter = frame >= cutFrame;

	// 0 -> 1 as we approach the cut from either side, driving the whip effect.
	const whip = interpolate(
		Math.abs(frame - cutFrame),
		[0, WHIP_HALF_WIDTH],
		[1, 0],
		{extrapolateRight: 'clamp'},
	);
	const whipBlur = whip * 22;
	const whipScaleX = 1 + whip * 0.3;
	const flashOpacity = whip * 0.85;

	// Before: a faint living zoom so it doesn't read as a dead frame.
	const beforeZoom = interpolate(frame, [0, beforeHoldFrames], [1, 1.045], {
		extrapolateLeft: 'clamp',
		extrapolateRight: 'clamp',
		easing: EASE_ENTER,
	});

	const beforeLabelOpacity = interpolate(
		frame,
		[6, 18, cutFrame - 10, cutFrame - 4],
		[0, 1, 1, 0],
		{extrapolateLeft: 'clamp', extrapolateRight: 'clamp'},
	);

	const afterLabelPop = interpolate(
		frame,
		[cutFrame + 5, cutFrame + 11],
		[0, 1],
		{extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: EASE_ENTER},
	);
	const afterLabelScale = interpolate(afterLabelPop, [0, 1], [0.7, 1]);

	return (
		<AbsoluteFill style={{backgroundColor: '#000'}}>
			<div
				style={{
					position: 'absolute',
					inset: 0,
					filter: whip > 0.01 ? `blur(${whipBlur}px)` : undefined,
					transform: whip > 0.01 ? `scaleX(${whipScaleX})` : undefined,
				}}
			>
				{isAfter ? (
					<OffthreadVideo
						src={staticFile(afterVideoSrc)}
						startFrom={0}
						style={{
							width: '100%',
							height: '100%',
							objectFit: 'cover',
						}}
					/>
				) : (
					<Img
						src={staticFile(beforeImageSrc)}
						style={{
							width: '100%',
							height: '100%',
							objectFit: 'cover',
							transform: `scale(${beforeZoom})`,
						}}
					/>
				)}
			</div>

			<AbsoluteFill
				style={{backgroundColor: BRAND.white, opacity: flashOpacity}}
			/>

			{!isAfter && (
				<Label
					text={labelBefore}
					opacity={beforeLabelOpacity}
					scale={1}
					side="left"
				/>
			)}
			{isAfter && (
				<Label
					text={labelAfter}
					opacity={afterLabelPop}
					scale={afterLabelScale}
					side="left"
				/>
			)}
		</AbsoluteFill>
	);
};

export const BeforeAfterReveal: React.FC<
	z.infer<typeof beforeAfterRevealSchema>
> = ({
	beforeImageSrc,
	afterVideoSrc,
	beforeHoldFrames,
	afterDurationFrames,
	labelBefore,
	labelAfter,
	iconSrc,
	wordmarkPrimary,
	wordmarkAccent,
	textColor,
	accentColor,
	plateColor,
	corner,
	iconSize,
	endCardHeadlineLine1,
	endCardHeadlineLine2,
	endCardTagline,
	endCardUrl,
	endCardBackgroundColor,
	endCardAccentColor2,
}) => {
	const mainDuration = beforeHoldFrames + afterDurationFrames;

	return (
		<AbsoluteFill>
			<Sequence from={0} durationInFrames={mainDuration}>
				<Reveal
					beforeImageSrc={beforeImageSrc}
					afterVideoSrc={afterVideoSrc}
					beforeHoldFrames={beforeHoldFrames}
					labelBefore={labelBefore}
					labelAfter={labelAfter}
				/>
				<BrandWatermark
					iconSrc={iconSrc}
					wordmarkPrimary={wordmarkPrimary}
					wordmarkAccent={wordmarkAccent}
					textColor={textColor}
					accentColor={accentColor}
					plateColor={plateColor}
					corner={corner}
					iconSize={iconSize}
				/>
			</Sequence>
			<Sequence from={mainDuration}>
				<EndCard
					iconSrc={iconSrc}
					textColor={textColor}
					accentColor={accentColor}
					headlineLine1={endCardHeadlineLine1}
					headlineLine2={endCardHeadlineLine2}
					tagline={endCardTagline}
					url={endCardUrl}
					backgroundColor={endCardBackgroundColor}
					accentColor2={endCardAccentColor2}
				/>
			</Sequence>
		</AbsoluteFill>
	);
};
